#!/usr/bin/env bash
# Regenerates the documentation screenshots in site/public/screenshots (README and website). Everything shown is
# fictional: a fresh, throwaway `pulse-docs` stack (deploy/compose.dev.yaml + scripts/screenshots/compose.yaml) on its
# own ports and volumes, invented clients, tools and events, credentials generated by that stack, and TEST-NET
# addresses. web/e2e/screenshots.spec.ts seeds it through the admin and public APIs and publishes a few events per
# second for PULSE_SCREENSHOTS_MINUTES (default 12) so the charts have shape. Never point this at a real instance.
#
# Usage: scripts/screenshots.sh [OUT_DIR]   (default site/public/screenshots)
#   KEEP=1  leave the pulse-docs stack running afterwards (default: docker compose down -v)
#
# Needs Docker, Go, pnpm and the Playwright browsers (cd web && pnpm exec playwright install chromium).
# Review every image before committing it.
set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
out=$(mkdir -p "${1:-$root/site/public/screenshots}" && cd "${1:-$root/site/public/screenshots}" && pwd)

export PULSE_DEV_ADMIN_PORT=${PULSE_DEV_ADMIN_PORT:-38080} PULSE_DEV_METRICS_PORT=${PULSE_DEV_METRICS_PORT:-39464}
export PULSE_DEV_PUBLIC_PORT=${PULSE_DEV_PUBLIC_PORT:-38443} PULSE_DEV_NATS_PORT=${PULSE_DEV_NATS_PORT:-34222}
export PULSE_DEV_ALLOY_PORT=${PULSE_DEV_ALLOY_PORT:-32345} PULSE_DEV_S3_PORT=${PULSE_DEV_S3_PORT:-38333}
compose=(docker compose -p pulse-docs -f "$root/deploy/compose.dev.yaml" -f "$root/scripts/screenshots/compose.yaml")

cleanup() {
  if [[ "${KEEP:-}" != 1 ]]; then "${compose[@]}" down -v >/dev/null 2>&1 || true; fi
}
trap cleanup EXIT

make -C "$root" deploy/.dev/master.key deploy/.dev/age.key >/dev/null
[[ -f "$root/sdk/ts/dist/pulse.browser.js" ]] || make -C "$root" sdk-build
"${compose[@]}" down -v >/dev/null 2>&1 || true # always start from empty volumes
"${compose[@]}" up -d --build --wait

cd "$root/web"
PULSE_E2E_URL="http://127.0.0.1:$PULSE_DEV_ADMIN_PORT" PULSE_E2E_PUBLIC_URL="http://127.0.0.1:$PULSE_DEV_PUBLIC_PORT" \
  PULSE_SCREENSHOTS_OUT="$out" pnpm exec playwright test e2e/screenshots.spec.ts --reporter=list
echo "screenshots written to $out"
